cat > src/main/java/GameOfLife.java <<'EOF'
import java.util.HashSet;
import java.util.Set;

public class GameOfLife {

    public Set<Cell> nextGeneration(Set<Cell> livingCells) {
        Set<Cell> survivors = new HashSet<>();
        for (Cell cell : livingCells) {
            if (livingNeighboursOf(cell, livingCells) == 2) {
                survivors.add(cell);
            }
        }
        return survivors;
    }

    private int livingNeighboursOf(Cell cell, Set<Cell> livingCells) {
        int count = 0;
        for (int dx = -1; dx <= 1; dx++) {
            for (int dy = -1; dy <= 1; dy++) {
                if ((dx != 0 || dy != 0)
                        && livingCells.contains(new Cell(cell.x() + dx, cell.y() + dy))) {
                    count++;
                }
            }
        }
        return count;
    }
}
EOF
